import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export const watchesKey = (sheetId: string, user: string) => ['sheet', sheetId, 'watches', user] as const;

/** The ids of the people on the sheet the user watches. */
export function useWatches(sheetId: string, user: string) {
  return useQuery({
    queryKey: watchesKey(sheetId, user),
    queryFn: () =>
      getJson<number[]>(`/api/sheets/${encodeURIComponent(sheetId)}/watches?user=${encodeURIComponent(user)}`),
  });
}
# The ids of the people on the sheet the user (?user=) watches. 404 for an id never loaded.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.watch.RespondWithWatched
  govern: [ readonly-transaction ]
# Start or stop the signed-in user watching a person (per user). Asking for the state already held changes nothing
# and writes no audit line. A refused watch (no signed-in user, unknown person) writes nothing.
validate:
  class: net.officefloor.hq.app.watch.ValidateWatch
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.watch.SaveWatch
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.watch.AuditPersonWatched
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.watch.RespondWithWatch
  govern: [ transaction ]
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Start or stop the user watching the loaded person; asking for the state already held changes nothing. */
public class SaveWatch {
    public void save(@Val WatchInput input, @Val Person loaded, WatchRepository watches, Out<WatchResponse> saved) {
        boolean now = watches.watching(loaded.sheetId(), loaded.id(), input.user());
        if (now == input.watched()) {
            saved.set(new WatchResponse(loaded.id(), now, false));
            return;
        }
        if (input.watched()) {
            watches.watch(loaded.sheetId(), loaded.id(), input.user());
        } else {
            watches.unwatch(loaded.sheetId(), loaded.id(), input.user());
        }
        saved.set(new WatchResponse(loaded.id(), input.watched(), true));
    }
}
